import logging
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(
        self, user: str, item: str, quantity: int, is_admin: bool = False, note: str = ""
    ) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            confirmation_message = (
                f"Order placed successfully for {quantity} x '{item}' (Reservation ID: {reservation_id})."
            )
            if note:
                confirmation_message += f" Note: {note}"
            return 200, confirmation_message
        except Exception as exc:
            error_code = str(uuid.uuid4())
            logger.error(
                "Unexpected error while placing order for user '%s' (Error Reference: %s)",
                user,
                error_code,
                exc_info=True,
            )

            if is_admin:
                msg = (
                    f"An unexpected error occurred (Reference code: {error_code}). "
                    f"Details: {type(exc).__name__}: {exc}"
                )
            else:
                msg = (
                    f"An unexpected error occurred while processing your order. "
                    f"Please contact support with reference code: {error_code}"
                )

            return 500, msg

    def cancel_order(self, reservation_id: int) -> tuple[int, str]:
        """Cancel an existing order by releasing its stock reservation.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            self.stock.release(reservation_id)
            confirmation_message = f"Order with reservation ID {reservation_id} has been cancelled successfully."
            return 200, confirmation_message
        except Exception as exc:
            error_code = str(uuid.uuid4())
            logger.error(
                "Unexpected error while cancelling order for reservation ID %s (Error Reference: %s)",
                reservation_id,
                error_code,
                exc_info=True,
            )
            msg = (
                f"An unexpected error occurred while cancelling your order. "
                f"Please contact support with reference code: {error_code}"
            )
            return 500, msg
